import json
from pathlib import Path
for name in ['extract.py','colors19.py','colors24.py','check19.png','check20.png','check21.png','check22.png']:
 Path(name).unlink(missing_ok=True)
p=Path('__pycache__')
if p.exists():
 for f in p.glob('*.pyc'):f.unlink()
 p.rmdir()
d=json.loads(Path('predictions.json').read_text())
assert set(d)=={f'fig_{i:02}.png' for i in range(1,31)}
print('predictions.json validated; 30 chart keys')
